// Differential-dump oracle: prints the same normalized token and AST-shape
// schema as `corexc dump-tokens` / `dump-ast`, using the Rust reference
// compiler library. Built by tests/selfhosting/dump.sh; not part of the
// workspace.

use corex::ast::*;
use corex::diagnostics::SourceFile;

