fn main() {
    let args: Vec<String> = std::env::args().skip(1).collect();
    if args.len() != 2 {
        eprintln!("usage: dump_oracle tokens|ast <file>");
        std::process::exit(2);
    }
    let mode = args[0].as_str();
    let text = std::fs::read_to_string(&args[1]).expect("read source");
    let file = SourceFile::new(args[1].clone(), text.clone());
    if mode == "tokens" {
        let tokens = corex::lexer::lex(&text).expect("lex");
        let mut out = String::new();
        for t in &tokens {
            let (line, col) = file.location(t.span.start);
            out.push_str(kname(&t.kind));
            out.push(' ');
            out.push_str(&format!("{line}:{col} "));
            out.push_str(&escape(&text[t.span.start..t.span.end]));
            out.push('\n');
        }
        print!("{out}");
        return;
    }
    let tokens = corex::lexer::lex(&text).expect("lex");
    let program = corex::parser::parse(&tokens).expect("parse");
    print!("{}", dump_ast(&program, &file));
}

fn escape(s: &str) -> String {
    let mut out = String::new();
    for b in s.bytes() {
        match b {
            b'\n' => out.push_str("\\n"),
            b'\t' => out.push_str("\\t"),
            b'\r' => out.push_str("\\r"),
            _ => out.push(b as char),
        }
    }
    out
}

struct Counts([i64; 37]);

impl Counts {
    fn inc(&mut self, i: usize) { self.0[i] += 1; }
}

fn cname(i: usize) -> &'static str {
    const NAMES: [&str; 37] = [
        "stmt.let", "stmt.assign", "stmt.compound_assign", "stmt.expr", "stmt.if",
        "stmt.while", "stmt.loop", "stmt.break", "stmt.continue", "stmt.return",
        "stmt.unsafe", "stmt.block", "stmt.switch", "stmt.case", "stmt.default",
        "stmt.empty", "expr.int", "expr.float", "expr.str", "expr.cstr", "expr.char",
        "expr.bool", "expr.null", "expr.ident", "expr.path", "expr.call", "expr.index",
        "expr.field", "expr.unary", "expr.binary", "expr.cast", "expr.sizeof",
        "expr.alignof", "expr.offsetof", "expr.structlit", "expr.arraylit",
        "expr.slicerange",
    ];
    NAMES[i]
}

fn dump_ast(program: &Program, file: &SourceFile) -> String {
    let mut items: Vec<(usize, &'static str, String)> = Vec::new();
    for f in &program.fns { items.push((f.name_span.start, "fn", f.name.clone())); }
    for s in &program.structs { items.push((s.name_span.start, "struct", s.name.clone())); }
    for e in &program.enums { items.push((e.name_span.start, "enum", e.name.clone())); }
    for t in &program.typedefs { items.push((t.name_span.start, "typedef", t.name.clone())); }
    for g in &program.globals { items.push((g.name_span.start, "static", g.name.clone())); }
    for c in &program.consts { items.push((c.name_span.start, "const", c.name.clone())); }
    items.sort_by_key(|i| i.0);

    let mut out = String::new();
    for (_, kind, name) in &items {
        out.push_str(&format!("item {kind} {name}\n"));
    }
    for f in &program.fns {
        let abi = if f.extern_abi.is_some() { "extern " } else { "" };
        let params: Vec<String> = f.params.iter().map(|p| p.ty.display()).collect();
        let ret = if f.ret == Type::Unit {
            String::new()
        } else {
            format!(" -> {}", f.ret.display())
        };
        out.push_str(&format!(
            "sig {abi}fn {}({}){ret}\n",
            f.name,
            params.join(", ")
        ));
    }

    let mut c = Counts([0; 37]);
    for f in &program.fns {
        if let Some(body) = &f.body {
            walk_block(&mut c, body);
        }
    }
    for g in &program.globals { walk_expr(&mut c, &g.init); }
    for k in &program.consts { walk_expr(&mut c, &k.value); }
    for e in &program.enums {
        for v in &e.variants {
            if let Some(x) = &v.value { walk_expr(&mut c, x); }
        }
    }
    for i in 0..37 {
        out.push_str(&format!("count {} {}\n", cname(i), c.0[i]));
    }
    let _ = file;
    out
}

fn walk_block(c: &mut Counts, b: &Block) {
    for s in &b.stmts { walk_stmt(c, s); }
}

fn walk_stmt(c: &mut Counts, s: &Stmt) {
    match s {
        Stmt::Let { init, .. } => { c.inc(0); walk_expr(c, init); }
        Stmt::Assign { target, value, .. } => {
            c.inc(1); walk_expr(c, target); walk_expr(c, value);
        }
        Stmt::CompoundAssign { target, value, .. } => {
            c.inc(2); walk_expr(c, target); walk_expr(c, value);
        }
        Stmt::Expr(e) => { c.inc(3); walk_expr(c, e); }
        Stmt::If { cond, then_block, else_branch, .. } => {
            c.inc(4); walk_expr(c, cond); walk_block(c, then_block);
            if let Some(b) = else_branch { walk_stmt(c, b); }
        }
        Stmt::While { cond, body, .. } => { c.inc(5); walk_expr(c, cond); walk_block(c, body); }
        Stmt::Loop { body, .. } => { c.inc(6); walk_block(c, body); }
        Stmt::Break(_) => c.inc(7),
        Stmt::Continue(_) => c.inc(8),
        Stmt::Return { value, .. } => { c.inc(9); if let Some(v) = value { walk_expr(c, v); } }
        Stmt::Unsafe { body, .. } => { c.inc(10); walk_block(c, body); }
        Stmt::Block(b) => { c.inc(11); walk_block(c, b); }
        Stmt::Switch { value, arms, .. } => {
            c.inc(12); walk_expr(c, value);
            for arm in arms {
                if let Some(v) = &arm.value { c.inc(13); walk_expr(c, v); } else { c.inc(14); }
                walk_block(c, &arm.body);
            }
        }
        Stmt::Empty(_) => c.inc(15),
        Stmt::For { init, cond, step, body, .. } => {
            if let Some(i) = init { walk_stmt(c, i); }
            if let Some(x) = cond { walk_expr(c, x); }
            if let Some(st) = step { walk_stmt(c, st); }
            walk_block(c, body);
        }
        Stmt::DoWhile { body, cond, .. } => { walk_block(c, body); walk_expr(c, cond); }
        Stmt::Label { stmt, .. } => walk_stmt(c, stmt),
        Stmt::Goto { .. } => {}
    }
}

fn walk_expr(c: &mut Counts, e: &Expr) {
    match &e.kind {
        ExprKind::Int(_) => c.inc(16),
        ExprKind::Float(_) => c.inc(17),
        ExprKind::Str(_) => c.inc(18),
        ExprKind::CStr(_) => c.inc(19),
        ExprKind::Char(_) => c.inc(20),
        ExprKind::Bool(_) => c.inc(21),
        ExprKind::Null => c.inc(22),
        ExprKind::Ident(_) => c.inc(23),
        ExprKind::Path(_) | ExprKind::EnumVariant { .. } => c.inc(24),
        ExprKind::SizeOf(_) => c.inc(31),
        ExprKind::AlignOf(_) => c.inc(32),
        ExprKind::OffsetOf(_, _) => c.inc(33),
        ExprKind::Field { base, .. } => { c.inc(27); walk_expr(c, base); }
        ExprKind::Unary { expr, .. } => { c.inc(28); walk_expr(c, expr); }
        ExprKind::Binary { lhs, rhs, .. } => { c.inc(29); walk_expr(c, lhs); walk_expr(c, rhs); }
        ExprKind::Cast { expr, .. } => { c.inc(30); walk_expr(c, expr); }
        ExprKind::Call { callee, args } => {
            c.inc(25); walk_expr(c, callee);
            for a in args { walk_expr(c, a); }
        }
        ExprKind::Index { base, index } => { c.inc(26); walk_expr(c, base); walk_expr(c, index); }
        ExprKind::SliceRange { base, start, end } => {
            c.inc(36); walk_expr(c, base);
            if let Some(s) = start { walk_expr(c, s); }
            if let Some(e) = end { walk_expr(c, e); }
        }
        ExprKind::StructLit { fields, .. } => {
            c.inc(34);
            for (_, v) in fields { walk_expr(c, v); }
        }
        ExprKind::CompoundLit { fields, .. } => {
            c.inc(34);
            for (_, v) in fields { walk_expr(c, v); }
        }
        ExprKind::Array(elems) => { c.inc(35); for x in elems { walk_expr(c, x); } }
        ExprKind::ArrayRepeat { value, .. } => { c.inc(35); walk_expr(c, value); }
    }
}
